// Hold types
export type HoldType = 'start' | 'hand' | 'foot' | 'finish';

// Hold type cycle order for tap-to-cycle on mobile
export const HOLD_TYPE_CYCLE: HoldType[] = ['hand', 'foot', 'start', 'finish'];
export type HoldSize = 'small' | 'medium' | 'large';

export interface Hold {
  id: string;
  x: number; // Percentage (0-100) relative to wall image
  y: number; // Percentage (0-100) relative to wall image
  type: HoldType;
  color: string; // Hex color
  sequence: number | null; // Optional sequence numbering
  size: HoldSize;
  notes?: string; // Optional per-hold notes
}

// Ascent - when someone climbs a route (public board-route tick contract)
export interface Ascent {
  id: string;
  route_id: string;
  user_id: string;
  user_name?: string;
  grade_v?: string; // User's suggested grade
  rating?: number; // User's rating (1-5)
  notes?: string;
  flashed?: boolean; // First try success
  created_at: string;
}

// Comment/Beta - user comments on routes
export interface Comment {
  id: string;
  route_id: string;
  user_id: string;
  user_name?: string;
  content: string;
  is_beta: boolean; // True if this is beta/tips for the climb
  created_at: string;
}

// Shared domain enums
export type ClimbDiscipline =
  | 'boulder'
  | 'sport'
  | 'trad'
  | 'top_rope'
  | 'board'
  | 'other';

export type GradeSystem = 'v_scale' | 'font' | 'yds' | 'custom';

export type AttemptOutcome = 'sent' | 'fell' | 'stopped';

export type SyncState = 'queued' | 'syncing' | 'failed' | 'synced';

export type OverlayStyle = 'stats' | 'attempt_timeline';

export type VenueKind = 'crag' | 'gym' | 'board';

export type RouteTerrain = 'slab' | 'vertical' | 'overhang' | 'roof';

export type ActivityEventKind = 'like' | 'comment' | 'follow' | 'crew_send';

// Route types
export interface Route {
  id: string;
  user_id: string;
  user_name?: string; // Setter's display name
  wall_id?: string | null;
  wall_image_url?: string; // Snapshot of wall image at route creation (for history)
  wall_image_width?: number;
  wall_image_height?: number;
  name: string;
  description?: string | null;
  grade_v?: string | null; // V-scale (V0, V1, V2, etc.)
  grade_font?: string | null; // Font scale (4, 5a, 6b+, etc.)
  rating?: number | null; // 1-5 star rating
  holds: Hold[];
  is_public: boolean;
  view_count: number;
  share_token?: string;
  created_at: string;
  updated_at: string;
  // Extended community attributes
  venue_id?: string | null;
  discipline?: ClimbDiscipline;
  grade_system?: GradeSystem;
  grade_label?: string | null;
  height_m?: number | null;
  rock_type?: string | null;
  terrain?: RouteTerrain | null;
  // Ascent data
  ascents?: Ascent[];
  // Comments/Beta
  comments?: Comment[];
  // Joined data
  wall?: Wall;
  venue?: CommunityVenue | null;
  user?: Profile;
  is_liked?: boolean;
  like_count?: number;
  liked_by?: string[]; // Array of user IDs who liked this route
  is_saved?: boolean;
}

// Wall types
export interface Wall {
  id: string;
  user_id: string;
  name: string;
  description?: string;
  image_url: string;
  image_width: number;
  image_height: number;
  is_public: boolean;
  created_at: string;
  updated_at: string;
}

// User profile
export interface Profile {
  id: string;
  username: string;
  full_name?: string | null;
  avatar_url?: string | null;
  bio?: string | null;
  home_area?: string | null;
  is_public?: boolean;
  created_at: string;
  updated_at?: string;
}

export interface ProfileDraft {
  id: string;
  username: string;
  full_name?: string | null;
  home_area?: string | null;
}

export interface ProfileUpdate {
  full_name?: string | null;
  username?: string | null;
  bio?: string | null;
  home_area?: string | null;
}

// Social graph: follow relationship between two profiles.
export interface Follow {
  follower_id: string;
  following_id: string;
  created_at: string;
}

// Follower/following counts returned by get_profile_follow_counts or search_climbers.
export interface ProfileFollowCounts {
  follower_count: number;
  following_count: number;
}

// One row of the following feed returned by get_following_feed.
// Clients enrich with route/profile data via the route_id/author_id keys.
export interface FollowingFeedItem {
  route_id: string;
  activity_at: string;
  author_id: string;
  author_username: string | null;
}

// Community catalog venues
export interface CommunityVenue {
  id: string;
  user_id?: string;
  name: string;
  kind: VenueKind;
  area: string | null;
  description: string | null;
  image_url: string | null;
  is_public?: boolean;
  created_at?: string;
  updated_at?: string;
}

// Canonical community route projection
export interface CommunityRoute {
  id: string;
  name: string;
  description: string | null;
  discipline: ClimbDiscipline;
  grade_system: GradeSystem;
  grade_label: string | null;
  height_m: number | null;
  rock_type: string | null;
  terrain: RouteTerrain | null;
  image_url: string | null;
  holds: Hold[];
  venue: CommunityVenue | null;
  author_id: string | null;
  is_saved: boolean;
  created_at: string;
}

// Climber projection for discovery search
export interface CommunityClimber {
  id: string;
  username: string | null;
  full_name: string | null;
  avatar_url: string | null;
  bio: string | null;
  home_area: string | null;
  is_followed: boolean;
  follower_count: number;
  following_count: number;
}

// Route bookmark (owner-only saved routes)
export interface RouteBookmark {
  user_id: string;
  route_id: string;
  created_at: string;
}

// Activity actor projection
export interface ActivityActor {
  id: string;
  username: string | null;
  full_name: string | null;
  avatar_url: string | null;
  home_area: string | null;
}

// Activity event (community notifications inbox)
export interface ActivityEvent {
  id: string;
  kind: ActivityEventKind;
  actor: ActivityActor;
  post_id: string | null;
  created_at: string;
  read_at: string | null;
}

// Private climbing session
export interface ClimbingSession {
  id: string;
  user_id: string;
  venue_name: string;
  conditions?: string | null;
  notes?: string | null;
  started_at: string;
  ended_at: string | null;
  created_at: string;
  updated_at: string;
}

// Private climb attempt (route_id replaces legacy board_route_id)
export interface ClimbAttempt {
  id: string;
  session_id: string;
  user_id: string;
  route_id: string | null;
  route_name: string;
  discipline: ClimbDiscipline;
  grade_system: GradeSystem;
  grade_label: string;
  outcome: AttemptOutcome;
  attempt_number: number;
  notes: string | null;
  occurred_at: string;
  created_at: string;
}

// Published session post
export interface SessionPost {
  id: string;
  user_id: string;
  session_id: string;
  featured_attempt_id: string;
  caption: string | null;
  image_path: string;
  image_alt: string;
  overlay_style: OverlayStyle;
  created_at: string;
  updated_at: string;
}

export interface SessionPostLike {
  post_id: string;
  user_id: string;
  created_at: string;
}

export interface SessionPostComment {
  id: string;
  post_id: string;
  user_id: string;
  content: string;
  created_at: string;
  updated_at: string;
}

// Feed projections
export interface FeedAuthor {
  id: string;
  username: string | null;
  full_name: string | null;
  avatar_url: string | null;
  bio: string | null;
  home_area: string | null;
  is_followed?: boolean;
}

export interface FeedFeaturedAttempt {
  id: string;
  route_id?: string | null;
  route_name: string;
  discipline: ClimbDiscipline;
  grade_system: GradeSystem;
  grade_label: string;
  outcome: AttemptOutcome;
  attempt_number: number;
  occurred_at: string;
}

export interface FeedAttemptTimelineItem {
  attempt_number: number;
  outcome: AttemptOutcome;
}

export interface FeedSessionSummary {
  id: string;
  venue_name: string;
  started_at: string;
  ended_at: string;
  duration_seconds: number;
  attempt_count: number;
  send_count: number;
  featured_attempt: FeedFeaturedAttempt;
  attempt_timeline?: FeedAttemptTimelineItem[] | null;
}

export interface SessionFeedItem {
  id: string;
  user_id: string;
  session_id: string;
  featured_attempt_id: string;
  caption: string | null;
  image_path: string;
  image_alt: string;
  overlay_style: OverlayStyle;
  created_at: string;
  updated_at: string;
  author: FeedAuthor;
  session: FeedSessionSummary;
  route: CommunityRoute | null;
  like_count: number;
  comment_count: number;
  is_liked: boolean;
}

export interface FeedCursor {
  created_at: string;
  id: string;
}

// Grade rankings & Profile statistics
export interface RankedGrade {
  system: GradeSystem;
  label: string;
  rank: number;
}

export interface ProfileStatistics {
  sessionCount: number;
  sendCount: number;
  attemptCount: number;
  sendRate: number | null;
  bestGrade: RankedGrade | null;
}

// Hold colors mapping
export const HOLD_COLORS: Record<HoldType, string> = {
  start: '#10b981',   // green
  hand: '#ef4444',    // red
  foot: '#3b82f6',    // blue
  finish: '#f59e0b',  // yellow
};

// Hold sizes mapping (as % of wall)
export const HOLD_SIZES: Record<HoldSize, string> = {
  small: '2.5%',
  medium: '4%',
  large: '7%',
};

// Hold border width mapping (in pixels)
export const HOLD_BORDER_WIDTH: Record<HoldSize, number> = {
  small: 2,     // Thin border
  medium: 3,    // Medium border
  large: 4,     // Thick border
};

// Grade options (V-scale)
export const V_GRADES = [
  'VB', 'V0', 'V1', 'V2', 'V3', 'V4', 'V5', 'V6', 'V7', 'V8', 'V9', 'V10',
  'V11', 'V12', 'V13', 'V14', 'V15', 'V16', 'V17'
];

