import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import {
  calculateDisplayGrade,
  calculateProfileStatistics,
  canonicalGrade,
  canonicalizeGrade,
  gradeLabelForRank,
  gradeRank,
  gradeToNumber,
  gradesForSystem,
  normalizeRouteGrades,
  numberToGrade,
  FONT_GRADES,
  V_GRADES,
  YDS_GRADES,
} from './grades.ts';
import type { ClimbAttempt, ClimbingSession } from '../types/index.ts';

describe('canonicalizeGrade', () => {
  it('canonicalizes case and surrounding whitespace', () => {
    assert.equal(canonicalizeGrade('  v0  '), 'V0');
    assert.equal(canonicalizeGrade(' vb'), 'VB');
    assert.equal(canonicalizeGrade('v17\t'), 'V17');
  });

  it('rejects non-string and invalid grades', () => {
    for (const value of [null, undefined, '', 'V18', 'not-a-grade', -1, 0, 17, 0.5, NaN, Infinity]) {
      assert.equal(canonicalizeGrade(value), undefined, `expected ${String(value)} to be unranked`);
    }
  });
});

describe('grade calculations', () => {
  it('returns a canonical setter grade when there are no ascents', () => {
    assert.equal(calculateDisplayGrade('  v4  ', []), 'V4');
    assert.equal(calculateDisplayGrade('v4'), 'V4');
    assert.equal(calculateDisplayGrade(undefined, []), undefined);
  });

  it('blends setter and ascent grades at equal weight', () => {
    assert.equal(calculateDisplayGrade('V4', [{ grade_v: 'V6' }]), 'V5');
    assert.equal(calculateDisplayGrade('V4', [{ grade_v: 'V6' }, { grade_v: 'V6' }]), 'V5');
  });

  it('ignores unranked ascents and still calculates ranked ascents', () => {
    assert.equal(calculateDisplayGrade(undefined, [{ grade_v: 'V2' }, { grade_v: 'V18' }]), 'V2');
    assert.equal(gradeToNumber('VB'), 0);
    assert.equal(gradeToNumber('V0'), 1);
    assert.equal(gradeToNumber('V17'), 18);
    assert.equal(numberToGrade(0), 'VB');
  });
});

describe('multi-system grade catalog', () => {
  it('exposes canonical grade catalogs matching native lists', () => {
    assert.deepEqual(gradesForSystem('v_scale'), V_GRADES);
    assert.deepEqual(gradesForSystem('font'), FONT_GRADES);
    assert.deepEqual(gradesForSystem('yds'), YDS_GRADES);
    assert.deepEqual(gradesForSystem('custom'), []);
  });

  it('canonicalizes grades across all supported systems', () => {
    assert.equal(canonicalGrade('  6a+ ', 'font'), '6a+');
    assert.equal(canonicalGrade('5.12A', 'yds'), '5.12a');
    assert.equal(canonicalGrade('  v10 ', 'v_scale'), 'V10');
    assert.equal(canonicalGrade('  Project 42  ', 'custom'), 'Project 42');
    assert.equal(canonicalGrade('', 'custom'), null);
    assert.equal(canonicalGrade('5.16a', 'yds'), null);
    assert.equal(canonicalGrade('invalid', 'font'), null);
  });

  it('computes ranks and reverse lookups correctly', () => {
    assert.equal(gradeRank('VB', 'v_scale'), 0);
    assert.equal(gradeRank('V17', 'v_scale'), 18);
    assert.equal(gradeRank('4', 'font'), 0);
    assert.equal(gradeRank('9a', 'font'), 22);
    assert.equal(gradeRank('5.0', 'yds'), 0);
    assert.equal(gradeRank('5.15d', 'yds'), 33);
    assert.equal(gradeRank('custom-thing', 'custom'), -1);

    assert.equal(gradeLabelForRank(0, 'v_scale'), 'VB');
    assert.equal(gradeLabelForRank(18, 'v_scale'), 'V17');
    assert.equal(gradeLabelForRank(0, 'font'), '4');
    assert.equal(gradeLabelForRank(0, 'yds'), '5.0');
    assert.equal(gradeLabelForRank(99, 'yds'), null);
  });
});

describe('calculateProfileStatistics', () => {
  it('returns empty statistics when sessions and attempts are empty', () => {
    const stats = calculateProfileStatistics([], []);
    assert.deepEqual(stats, {
      sessionCount: 0,
      sendCount: 0,
      attemptCount: 0,
      sendRate: null,
      bestGrade: null,
    });
  });

  it('calculates send counts, send rate, and best grade across systems', () => {
    const sessions: ClimbingSession[] = [
      {
        id: 's1',
        user_id: 'u1',
        venue_name: 'Gym',
        started_at: '2026-09-01T10:00:00Z',
        ended_at: '2026-09-01T12:00:00Z',
        created_at: '2026-09-01T10:00:00Z',
        updated_at: '2026-09-01T12:00:00Z',
      },
    ];

    const attempts: ClimbAttempt[] = [
      {
        id: 'a1',
        session_id: 's1',
        user_id: 'u1',
        route_id: null,
        route_name: 'Warmup',
        discipline: 'boulder',
        grade_system: 'v_scale',
        grade_label: 'V3',
        outcome: 'sent',
        attempt_number: 1,
        notes: null,
        occurred_at: '2026-09-01T10:15:00Z',
        created_at: '2026-09-01T10:15:00Z',
      },
      {
        id: 'a2',
        session_id: 's1',
        user_id: 'u1',
        route_id: null,
        route_name: 'Project',
        discipline: 'sport',
        grade_system: 'yds',
        grade_label: '5.12a',
        outcome: 'sent',
        attempt_number: 2,
        notes: null,
        occurred_at: '2026-09-01T11:00:00Z',
        created_at: '2026-09-01T11:00:00Z',
      },
      {
        id: 'a3',
        session_id: 's1',
        user_id: 'u1',
        route_id: null,
        route_name: 'High Project',
        discipline: 'sport',
        grade_system: 'yds',
        grade_label: '5.13a',
        outcome: 'fell',
        attempt_number: 1,
        notes: null,
        occurred_at: '2026-09-01T11:30:00Z',
