  it('ignores fallen attempts and custom unranked attempts when computing best grade', () => {
    const sessions: ClimbingSession[] = [
      {
        id: 's1',
        user_id: 'u1',
        venue_name: 'Outdoor',
        started_at: '2026-09-01T10:00:00Z',
        ended_at: '2026-09-01T12:00:00Z',
        created_at: '2026-09-01T10:00:00Z',
        updated_at: '2026-09-01T12:00:00Z',
      },
    ];

    const attempts: ClimbAttempt[] = [
      {
        id: 'a1',
        session_id: 's1',
        user_id: 'u1',
        route_id: null,
        route_name: 'Fell Hard',
        discipline: 'boulder',
        grade_system: 'v_scale',
        grade_label: 'V15',
        outcome: 'fell',
        attempt_number: 1,
        notes: null,
        occurred_at: '2026-09-01T10:15:00Z',
        created_at: '2026-09-01T10:15:00Z',
      },
      {
        id: 'a2',
        session_id: 's1',
        user_id: 'u1',
        route_id: null,
        route_name: 'Custom Send',
        discipline: 'other',
        grade_system: 'custom',
        grade_label: 'Mega Route',
        outcome: 'sent',
        attempt_number: 1,
        notes: null,
        occurred_at: '2026-09-01T10:30:00Z',
