import type {
  Ascent,
  ClimbAttempt,
  ClimbingSession,
  GradeSystem,
  ProfileStatistics,
  RankedGrade,
  Route,
} from '../types/index.ts';
import { V_GRADES } from '../types/index.ts';

export { V_GRADES };

export const FONT_GRADES: readonly string[] = [
  '4', '5a', '5b', '5c', '6a', '6a+', '6b', '6b+', '6c', '6c+',
  '7a', '7a+', '7b', '7b+', '7c', '7c+', '8a', '8a+', '8b', '8b+',
  '8c', '8c+', '9a'
];

export const YDS_GRADES: readonly string[] = [
  '5.0', '5.1', '5.2', '5.3', '5.4', '5.5', '5.6', '5.7', '5.8', '5.9',
  '5.10a', '5.10b', '5.10c', '5.10d', '5.11a', '5.11b', '5.11c', '5.11d',
  '5.12a', '5.12b', '5.12c', '5.12d', '5.13a', '5.13b', '5.13c', '5.13d',
  '5.14a', '5.14b', '5.14c', '5.14d', '5.15a', '5.15b', '5.15c', '5.15d'
];

export type GradeInput = string | null | undefined;

/**
 * Returns the ordered canonical list of grade labels for a system.
 * Custom grades have no intrinsic ordering and return an empty list.
 */
export const gradesForSystem = (system: GradeSystem): readonly string[] => {
  switch (system) {
    case 'v_scale':
      return V_GRADES;
    case 'font':
      return FONT_GRADES;
    case 'yds':
      return YDS_GRADES;
    case 'custom':
      return [];
  }
};

/**
 * Returns the canonical label for a grade within its system, or null when
 * the label is not a member of the system's catalog. Custom labels are trimmed.
 */
export const canonicalGrade = (
  label: GradeInput,
  system: GradeSystem
): string | null => {
  if (typeof label !== 'string') return null;
  const trimmed = label.trim();
  if (!trimmed) return null;
  if (system === 'custom') return trimmed;

  const catalog = gradesForSystem(system);
  const found = catalog.find((g) => g.toLowerCase() === trimmed.toLowerCase());
  return found ?? null;
};

/**
 * Zero-based rank within the system's ordering, or -1 for unknown/custom.
 */
export const gradeRank = (
  label: GradeInput,
  system: GradeSystem
): number => {
  const canonical = canonicalGrade(label, system);
  if (!canonical) return -1;
  const catalog = gradesForSystem(system);
  const index = catalog.indexOf(canonical);
  return index >= 0 ? index : -1;
};

/**
 * Returns the grade label for a zero-based rank within a system, or null if out of range.
 */
export const gradeLabelForRank = (
  rank: number,
  system: GradeSystem
): string | null => {
  const catalog = gradesForSystem(system);
  if (rank >= 0 && rank < catalog.length) {
    return catalog[rank];
  }
  return null;
};

/** Convert an unknown runtime value to a canonical V-scale label. */
export const canonicalizeGrade = (grade: unknown): string | undefined => {
  if (typeof grade !== 'string') return undefined;
  const canonical = grade.trim().toUpperCase();
  return V_GRADES.includes(canonical) ? canonical : undefined;
};

type RuntimeGradeRoute = Omit<Route, 'grade_v' | 'ascents'> & {
  grade_v?: GradeInput;
  ascents?: Array<Omit<Ascent, 'grade_v'> & { grade_v?: GradeInput }>;
};

/**
 * Normalize route and nested ascent grades at a data ingress boundary.
 * The returned route remains typed with string-only Route/Ascent fields.
 */
export const normalizeRouteGrades = (route: RuntimeGradeRoute): Route => ({
  ...route,
  grade_v: canonicalizeGrade(route.grade_v),
  ascents: route.ascents?.map((ascent) => ({
    ...ascent,
    grade_v: canonicalizeGrade(ascent.grade_v),
  })),
});

export const gradeToNumber = (grade?: GradeInput): number => {
  const canonical = canonicalizeGrade(grade);
  if (!canonical) return -1;
  const index = V_GRADES.indexOf(canonical);
  return index >= 0 ? index : -1;
};

export const numberToGrade = (num: number): string | undefined => {
  const rounded = Math.round(num);
  if (rounded >= 0 && rounded < V_GRADES.length) {
    return V_GRADES[rounded];
  }
  return undefined;
};

export const calculateDisplayGrade = (
  setterGrade?: GradeInput,
  ascents?: Array<{ grade_v?: GradeInput }>
): string | undefined => {
  const canonicalSetter = canonicalizeGrade(setterGrade);
  const setterNum = gradeToNumber(canonicalSetter);
  const userGrades = (ascents || [])
    .map((a) => gradeToNumber(a.grade_v))
    .filter((g) => g >= 0);

  if (setterNum < 0 && userGrades.length === 0) return undefined;
  if (setterNum >= 0 && userGrades.length === 0) return canonicalSetter;

  const avgUser = userGrades.reduce((sum, g) => sum + g, 0) / userGrades.length;

  if (setterNum < 0) return numberToGrade(avgUser);

  return numberToGrade(setterNum * 0.5 + avgUser * 0.5);
};

/**
 * Session-derived profile statistics calculated from private sessions and
 * attempts only. Matches native ProfileStatisticsCalculator logic.
 */
export const calculateProfileStatistics = (
  sessions: readonly ClimbingSession[],
  attempts: readonly ClimbAttempt[]
): ProfileStatistics => {
  const sessionCount = sessions.length;
  const attemptCount = attempts.length;
  const sentAttempts = attempts.filter((a) => a.outcome === 'sent');
  const sendCount = sentAttempts.length;
  const sendRate = attemptCount > 0 ? sendCount / attemptCount : null;

  let bestGrade: RankedGrade | null = null;

  for (const attempt of sentAttempts) {
    const rank = gradeRank(attempt.grade_label, attempt.grade_system);
    if (rank < 0) continue;

    const candidate: RankedGrade = {
      system: attempt.grade_system,
      label: attempt.grade_label,
      rank,
    };

    if (!bestGrade) {
      bestGrade = candidate;
    } else if (candidate.rank > bestGrade.rank) {
      bestGrade = candidate;
    } else if (
      candidate.rank === bestGrade.rank &&
      candidate.label.localeCompare(bestGrade.label) > 0
    ) {
      bestGrade = candidate;
    }
  }

  return {
    sessionCount,
    sendCount,
    attemptCount,
    sendRate,
    bestGrade,
  };
};

supabase/migrations/014_community_prereq:
-- 014_community_prerequisites.sql
-- Additive migration implementing the V1 community contract:
-- 1. Venues catalog with honest nullable metadata
-- 2. Extended route catalog (outdoor/crag support, nullable wall_id, venue_id, discipline, grade system, metadata)
-- 3. Cutover climb_attempts.board_route_id to route_id
-- 4. Private climbing session conditions & notes
-- 5. Public social follows table and relationship counts
-- 6. Owner-only route bookmarks
-- 7. Activity events inbox driven by real social transitions
-- 8. Updated get_session_feed RPC (author.is_followed, top-level route, attempt.route_id, following_only filter)
-- 9. Community discovery RPCs: get_explore_routes, search_climbers, get_activity

-- ============================================================================
-- 1. VENUES TABLE & PRIVACY LIFECYCLE
-- ============================================================================
CREATE TABLE IF NOT EXISTS public.venues (
  id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
  user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  name TEXT NOT NULL CHECK (length(trim(name)) >= 1 AND length(name) <= 120),
  kind TEXT NOT NULL CHECK (kind IN ('crag', 'gym', 'board')),
  area TEXT CHECK (area IS NULL OR (length(trim(area)) >= 1 AND length(area) <= 120)),
  description TEXT CHECK (description IS NULL OR length(description) <= 2000),
  image_url TEXT CHECK (image_url IS NULL OR length(image_url) <= 1000),
  is_public BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_venues_is_public ON public.venues(is_public);
CREATE INDEX IF NOT EXISTS idx_venues_user_id ON public.venues(user_id);
CREATE INDEX IF NOT EXISTS idx_venues_kind ON public.venues(kind);

ALTER TABLE public.venues ENABLE ROW LEVEL SECURITY;

CREATE POLICY "venues_select_visible" ON public.venues
  FOR SELECT TO anon, authenticated
  USING (
    is_public = true
    OR auth.uid() = user_id
    OR public.is_moderator()
  );

CREATE POLICY "venues_insert_owner" ON public.venues
  FOR INSERT TO authenticated
  WITH CHECK (auth.uid() = user_id);

CREATE POLICY "venues_update_owner" ON public.venues
  FOR UPDATE TO authenticated
  USING (auth.uid() = user_id OR public.is_moderator())
  WITH CHECK (auth.uid() = user_id OR public.is_moderator());

CREATE POLICY "venues_delete_owner" ON public.venues
  FOR DELETE TO authenticated
  USING (auth.uid() = user_id OR public.is_moderator());

REVOKE ALL ON TABLE public.venues FROM PUBLIC, anon, authenticated;
GRANT SELECT ON TABLE public.venues TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON TABLE public.venues TO authenticated;

-- ============================================================================
-- 2. WALL AND VENUE DELETION PRIVACY (PREVENT PRIVATIZED ROUTES BECOMING PUBLIC)
-- ============================================================================
-- Deleted private wall tombstone table: ensures that deleted private walls are never
-- classified as local/missing walls by security predicates.
CREATE TABLE IF NOT EXISTS public.deleted_private_walls (
  wall_id TEXT PRIMARY KEY,
  deleted_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

ALTER TABLE public.deleted_private_walls ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.deleted_private_walls FROM PUBLIC, anon, authenticated;

-- When a private wall is deleted, record its tombstone and privatize all child routes
CREATE OR REPLACE FUNCTION public.handle_wall_deletion_privacy()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF OLD.is_public IS DISTINCT FROM true THEN
    INSERT INTO public.deleted_private_walls (wall_id)
    VALUES (OLD.id::text)
    ON CONFLICT (wall_id) DO NOTHING;

    UPDATE public.routes
       SET is_public = false
     WHERE wall_id = OLD.id::text;
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS trg_wall_deletion_privacy ON public.walls;
CREATE TRIGGER trg_wall_deletion_privacy
  BEFORE DELETE ON public.walls
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_wall_deletion_privacy();

-- When a private venue is deleted, privatize all surviving child routes so they never fall open
CREATE OR REPLACE FUNCTION public.handle_venue_deletion_privacy()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF OLD.is_public IS DISTINCT FROM true THEN
    UPDATE public.routes
       SET is_public = false
     WHERE venue_id = OLD.id;
  END IF;
  RETURN OLD;
END;
$$;

DROP TRIGGER IF EXISTS trg_venue_deletion_privacy ON public.venues;
CREATE TRIGGER trg_venue_deletion_privacy
  BEFORE DELETE ON public.venues
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_venue_deletion_privacy();

-- ============================================================================
-- 3. EXTEND ROUTES TABLE
-- ============================================================================
-- wall_id is nullable for outdoor/crag routes (no fake wall IDs)
ALTER TABLE public.routes ALTER COLUMN wall_id DROP NOT NULL;

-- Add venue link and physical/community climbing metadata
ALTER TABLE public.routes
  ADD COLUMN IF NOT EXISTS venue_id UUID REFERENCES public.venues(id) ON DELETE SET NULL,
  ADD COLUMN IF NOT EXISTS discipline TEXT NOT NULL DEFAULT 'board'
    CHECK (discipline IN ('boulder', 'sport', 'trad', 'top_rope', 'board', 'other')),
  ADD COLUMN IF NOT EXISTS grade_system TEXT NOT NULL DEFAULT 'v_scale'
    CHECK (grade_system IN ('v_scale', 'font', 'yds', 'custom')),
  ADD COLUMN IF NOT EXISTS grade_label TEXT
    CHECK (grade_label IS NULL OR length(grade_label) <= 24),
  ADD COLUMN IF NOT EXISTS height_m NUMERIC(6, 2)
    CHECK (height_m IS NULL OR height_m > 0),
  ADD COLUMN IF NOT EXISTS rock_type TEXT
    CHECK (rock_type IS NULL OR (length(trim(rock_type)) >= 1 AND length(rock_type) <= 120)),
  ADD COLUMN IF NOT EXISTS terrain TEXT
    CHECK (terrain IS NULL OR terrain IN ('slab', 'vertical', 'overhang', 'roof'));

-- Backfill existing routes: preserve existing grade_v/grade_font; populate canonical grade_label
-- only if representable within the 24-char constraint to guarantee zero migration aborts.
UPDATE public.routes
   SET grade_label = CASE
         WHEN length(trim(COALESCE(grade_v, grade_font))) <= 24
         THEN trim(COALESCE(grade_v, grade_font))
         ELSE NULL
       END,
       grade_system = CASE
         WHEN grade_v IS NOT NULL THEN 'v_scale'
         WHEN grade_font IS NOT NULL THEN 'font'
         ELSE grade_system
       END
 WHERE grade_label IS NULL AND (grade_v IS NOT NULL OR grade_font IS NOT NULL);

CREATE INDEX IF NOT EXISTS idx_routes_venue_id ON public.routes(venue_id);
CREATE INDEX IF NOT EXISTS idx_routes_discipline ON public.routes(discipline);
CREATE INDEX IF NOT EXISTS idx_routes_grade_system ON public.routes(grade_system);

-- ============================================================================
-- 4. PARENT VISIBILITY SECURITY DEFINER PREDICATES
-- Fixed search_path SECURITY DEFINER predicates that bypass caller RLS on parent
-- tables (walls, venues) to reliably distinguish genuinely missing/local records
-- from existing hidden/private records, while enforcing caller owner/moderator/public rules.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.is_wall_accessible(target_wall_id TEXT)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT CASE
    -- NULL wall_id (e.g. outdoor crag routes) requires no wall
    WHEN target_wall_id IS NULL THEN true
    -- Deleted private wall tombstone: always inaccessible to preserve privacy
    WHEN EXISTS (SELECT 1 FROM public.deleted_private_walls WHERE wall_id = target_wall_id) THEN false
    -- If the wall exists in public.walls, it MUST be public, caller-owned, or caller is moderator
    WHEN EXISTS (SELECT 1 FROM public.walls WHERE id::text = target_wall_id) THEN
      EXISTS (
        SELECT 1 FROM public.walls
         WHERE id::text = target_wall_id
           AND (is_public = true OR user_id = auth.uid() OR public.is_moderator())
      )
    -- Local/unregistered wall IDs (e.g. 'default-wall') with no server record are allowed
    ELSE true
  END;
$$;
REVOKE ALL ON FUNCTION public.is_wall_accessible(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_wall_accessible(text) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.is_venue_accessible(target_venue_id UUID)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT CASE
    WHEN target_venue_id IS NULL THEN true
    ELSE EXISTS (
      SELECT 1 FROM public.venues
       WHERE id = target_venue_id
         AND (is_public = true OR user_id = auth.uid() OR public.is_moderator())
    )
  END;
$$;
REVOKE ALL ON FUNCTION public.is_venue_accessible(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_venue_accessible(uuid) TO anon, authenticated;

CREATE OR REPLACE FUNCTION public.is_route_accessible(target_route_id UUID)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.routes r
     WHERE r.id = target_route_id
       AND (r.is_public = true OR r.user_id = auth.uid() OR public.is_moderator())
       AND public.is_wall_accessible(r.wall_id)
       AND public.is_venue_accessible(r.venue_id)
  );
$$;
REVOKE ALL ON FUNCTION public.is_route_accessible(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_route_accessible(uuid) TO anon, authenticated;

-- Enforce underlying wall and venue visibility for public routes:
-- A public route on a private wall or private venue cannot be viewed by everyone.
DROP POLICY IF EXISTS "Public routes are viewable by everyone" ON public.routes;
CREATE POLICY "Public routes are viewable by everyone" ON public.routes
  FOR SELECT TO anon, authenticated
  USING (
    is_public = true
    AND public.is_wall_accessible(wall_id)
    AND public.is_venue_accessible(venue_id)
  );

-- ============================================================================
-- 5. SECURE ROUTE VIEW COUNT RPC (REPLACES 007 WITH PARENT VISIBILITY CHECKS)
-- ============================================================================
CREATE OR REPLACE FUNCTION public.increment_route_view(target_route_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  next_count INTEGER;
BEGIN
  IF NOT public.is_route_accessible(target_route_id) THEN
    RETURN NULL;
  END IF;

  UPDATE public.routes
     SET view_count = COALESCE(view_count, 0) + 1
   WHERE id = target_route_id
  RETURNING view_count INTO next_count;

  RETURN next_count;
END;
$$;
REVOKE ALL ON FUNCTION public.increment_route_view(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.increment_route_view(uuid) TO anon, authenticated;

-- ============================================================================
-- 6. CLIMBING SESSIONS PRIVATE CONTEXT (CONDITIONS & NOTES)
-- ============================================================================
ALTER TABLE public.climbing_sessions
  ADD COLUMN IF NOT EXISTS conditions TEXT
    CHECK (conditions IS NULL OR (length(trim(conditions)) >= 1 AND length(conditions) <= 500)),
  ADD COLUMN IF NOT EXISTS notes TEXT
    CHECK (notes IS NULL OR (length(trim(notes)) >= 1 AND length(notes) <= 1000));

-- ============================================================================
-- 7. ATTEMPT LINK CUTOVER: board_route_id -> route_id
-- ============================================================================
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_schema = 'public'
       AND table_name = 'climb_attempts'
       AND column_name = 'board_route_id'
  ) THEN
    ALTER TABLE public.climb_attempts RENAME COLUMN board_route_id TO route_id;
  END IF;
END $$;

ALTER INDEX IF EXISTS public.idx_climb_attempts_board_route_id RENAME TO idx_climb_attempts_route_id;
CREATE INDEX IF NOT EXISTS idx_climb_attempts_route_id ON public.climb_attempts(route_id);

-- ============================================================================
-- 8. DEDICATED PER-TABLE IMMUTABILITY TRIGGERS (DATA-V1-001)
-- Table-specific trigger functions avoid referencing absent fields during PL/pgSQL compilation.
-- ============================================================================
CREATE OR REPLACE FUNCTION public.prevent_climbing_session_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'session user_id is immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS prevent_climbing_session_parent_change ON public.climbing_sessions;
DROP TRIGGER IF EXISTS trg_climbing_sessions_prevent_parent_change ON public.climbing_sessions;
CREATE TRIGGER prevent_climbing_session_parent_change
  BEFORE UPDATE ON public.climbing_sessions
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_climbing_session_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_climb_attempt_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.session_id IS DISTINCT FROM OLD.session_id THEN
    RAISE EXCEPTION 'attempt ownership and parent keys are immutable' USING ERRCODE = '42501';
  END IF;

  IF NEW.route_id IS DISTINCT FROM OLD.route_id
     AND NOT (
       OLD.route_id IS NOT NULL
       AND NEW.route_id IS NULL
       AND NOT EXISTS (
         SELECT 1 FROM public.routes AS r WHERE r.id = OLD.route_id
       )
     ) THEN
    RAISE EXCEPTION 'attempt route_id is immutable while the route exists' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_climb_attempt_parent_change ON public.climb_attempts;
DROP TRIGGER IF EXISTS trg_climb_attempts_prevent_parent_change ON public.climb_attempts;
CREATE TRIGGER prevent_climb_attempt_parent_change
  BEFORE UPDATE ON public.climb_attempts
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_climb_attempt_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_session_post_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at
     OR NEW.user_id IS DISTINCT FROM OLD.user_id
     OR NEW.session_id IS DISTINCT FROM OLD.session_id
     OR NEW.featured_attempt_id IS DISTINCT FROM OLD.featured_attempt_id THEN
    RAISE EXCEPTION 'post identity, cursor fields, ownership, session_id, and featured_attempt_id are immutable'
      USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_session_post_parent_change ON public.session_posts;
DROP TRIGGER IF EXISTS trg_session_posts_prevent_parent_change ON public.session_posts;
CREATE TRIGGER prevent_session_post_parent_change
  BEFORE UPDATE ON public.session_posts
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_session_post_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_session_post_like_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.post_id IS DISTINCT FROM OLD.post_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'like parent and owner are immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_session_post_like_parent_change ON public.session_post_likes;
DROP TRIGGER IF EXISTS trg_session_post_likes_prevent_parent_change ON public.session_post_likes;
CREATE TRIGGER prevent_session_post_like_parent_change
  BEFORE UPDATE ON public.session_post_likes
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_session_post_like_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_session_post_comment_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.post_id IS DISTINCT FROM OLD.post_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'comment identity, parent, and owner are immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_session_post_comment_parent_change ON public.session_post_comments;
DROP TRIGGER IF EXISTS trg_session_post_comments_prevent_parent_change ON public.session_post_comments;
CREATE TRIGGER prevent_session_post_comment_parent_change
  BEFORE UPDATE ON public.session_post_comments
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_session_post_comment_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_venue_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'venue user_id is immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_venue_parent_change ON public.venues;
DROP TRIGGER IF EXISTS trg_venues_prevent_parent_change ON public.venues;
CREATE TRIGGER prevent_venue_parent_change
  BEFORE UPDATE ON public.venues
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_venue_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_meetup_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.organizer_id IS DISTINCT FROM OLD.organizer_id THEN
    RAISE EXCEPTION 'meetup organizer_id is immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_meetup_parent_change ON public.meetups;
DROP TRIGGER IF EXISTS trg_meetups_prevent_parent_change ON public.meetups;
CREATE TRIGGER prevent_meetup_parent_change
  BEFORE UPDATE ON public.meetups
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_meetup_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_meetup_attendance_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.meetup_id IS DISTINCT FROM OLD.meetup_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'attendance parent and owner are immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_meetup_attendance_parent_change ON public.meetup_attendees;
DROP TRIGGER IF EXISTS trg_meetup_attendees_prevent_parent_change ON public.meetup_attendees;
CREATE TRIGGER prevent_meetup_attendance_parent_change
  BEFORE UPDATE ON public.meetup_attendees
  FOR EACH ROW
  EXECUTE FUNCTION public.prevent_meetup_attendance_parent_change();

CREATE OR REPLACE FUNCTION public.prevent_meetup_comment_parent_change()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF NEW.meetup_id IS DISTINCT FROM OLD.meetup_id
     OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN
    RAISE EXCEPTION 'meetup comment parent and owner are immutable' USING ERRCODE = '42501';
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS prevent_meetup_comment_parent_change ON public.meetup_comments;
DROP TRIGGER IF EXISTS trg_meetup_comments_prevent_parent_change ON public.meetup_comments;
CREATE TRIGGER prevent_meetup_comment_parent_change
  BEFORE UPDATE ON public.meetup_comments
  FOR EACH ROW
