def assert_public_meetups_and_joins(base: str, owner_token: str, other_token: str) -> None:
    public = rows(
        expect_api_result(request_json("GET", f"{base}/rest/v1/meetups?id=in.({OWNER_MEETUP_ID},{CANCELLED_MEETUP_ID})&select=id,status"), "anonymous meetup read"),
        "anonymous meetup read",
    )
    if {item.get("id") for item in public} != {OWNER_MEETUP_ID, CANCELLED_MEETUP_ID}:
        fail(f"public meetup read omitted status variants: {public!r}")
    assert_rejected(rpc(base, "join_meetup", owner_token, {"meetup_id": OWNER_MEETUP_ID}), "organizer join")
    first = rpc(base, "join_meetup", other_token, {"meetup_id": OWNER_MEETUP_ID})
    if first.status != 200:
        fail(f"first meetup join failed: HTTP {first.status} {first.body!r}")
    second = rpc(base, "join_meetup", other_token, {"meetup_id": OWNER_MEETUP_ID})
    if second.status != 200 or second.body != first.body:
        fail(f"meetup join was not idempotent: first={first.body!r} second={second.body!r}")
    assert_rejected(rpc(base, "join_meetup", payload={"meetup_id": OWNER_MEETUP_ID}), "anonymous meetup join")
    owner_other = rpc(base, "join_meetup", owner_token, {"meetup_id": OTHER_MEETUP_ID})
    if owner_other.status != 200:
        fail(f"owner join of other meetup failed: HTTP {owner_other.status} {owner_other.body!r}")
    assert_rejected(
        expect_api_result(
            request_json(
                "PATCH",
                f"{base}/rest/v1/meetup_attendees?meetup_id=eq.{OTHER_MEETUP_ID}&user_id=eq.{OWNER_ID}",
                owner_token,
                {"meetup_id": OWNER_MEETUP_ID},
            ),
            "owner attendee parent mutation",
        ),
        "owner attendee parent mutation",
    )
    assert_rejected(
        expect_api_result(
            request_json(
                "PATCH",
                f"{base}/rest/v1/meetup_attendees?meetup_id=eq.{OTHER_MEETUP_ID}&user_id=eq.{OWNER_ID}",
                owner_token,
                {"user_id": OTHER_ID},
            ),
            "owner attendee user mutation",
        ),
        "owner attendee user mutation",
    )
    leave = expect_api_result(
        request_json(
            "DELETE",
            f"{base}/rest/v1/meetup_attendees?meetup_id=eq.{OTHER_MEETUP_ID}&user_id=eq.{OWNER_ID}",
            owner_token,
        ),
        "attendee leave",
    )
    if leave.status != 200:
        fail(f"attendee leave failed: HTTP {leave.status} {leave.body!r}")
    if rows(
        expect_api_result(
            request_json(
                "GET",
                f"{base}/rest/v1/meetup_attendees?meetup_id=eq.{OTHER_MEETUP_ID}&user_id=eq.{OWNER_ID}&select=user_id",
            ),
            "attendee leave verification",
        ),
        "attendee leave verification",
    ):
        fail("attendee leave left an attendance row")
    if rpc(base, "join_meetup", owner_token, {"meetup_id": OTHER_MEETUP_ID}).status != 200:
        fail("attendee could not rejoin after leaving")
    owner_filler = rpc(base, "join_meetup", owner_token, {"meetup_id": FILLER_MEETUP_ID})
    if owner_filler.status != 200:
        fail(f"owner join of filler meetup failed: HTTP {owner_filler.status} {owner_filler.body!r}")
    assert_rejected(rpc(base, "join_meetup", other_token, {"meetup_id": FILLER_MEETUP_ID}), "full meetup join")
    assert_rejected(rpc(base, "join_meetup", other_token, {"meetup_id": CANCELLED_MEETUP_ID}), "cancelled meetup join")
    assert_rejected(rpc(base, "join_meetup", other_token, {"meetup_id": PAST_MEETUP_ID}), "past meetup join")

    barrier = threading.Barrier(2)

    def synchronized_join(token: str) -> ApiResult:
        barrier.wait(timeout=15)
        return rpc(base, "join_meetup", token, {"meetup_id": RACE_MEETUP_ID})

    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = [executor.submit(synchronized_join, token) for token in (owner_token, other_token)]
        race_results = [future.result() for future in futures]
    successes = [result for result in race_results if 200 <= result.status < 300]
    full_results = [result for result in race_results if not 200 <= result.status < 300]
    if len(successes) != 1 or len(full_results) != 1:
        fail(f"concurrent final-slot contention was not one success/full result: {race_results!r}")
    assert_rejected(full_results[0], "concurrent full meetup join")
    race_attendees = rows(
        expect_api_result(
            request_json(
                "GET",
                f"{base}/rest/v1/meetup_attendees?meetup_id=eq.{RACE_MEETUP_ID}&select=user_id",
            ),
            "concurrent attendee count",
        ),
        "concurrent attendee count",
    )
    if len(race_attendees) != 1 or race_attendees[0].get("user_id") not in {OWNER_ID, OTHER_ID}:
        fail(f"concurrent capacity admitted the wrong attendee count: {race_attendees!r}")

    cancelled_update = expect_api_result(request_json("PATCH", f"{base}/rest/v1/meetups?id=eq.{OWNER_MEETUP_ID}", owner_token, {"status": "cancelled"}), "organizer cancellation")
    if cancelled_update.status != 200:
        fail(f"organizer cancellation failed: HTTP {cancelled_update.status} {cancelled_update.body!r}")
    # Existing attendance remains idempotent after cancellation.
    if rpc(base, "join_meetup", other_token, {"meetup_id": OWNER_MEETUP_ID}).status != 200:
        fail("existing attendee lost idempotence after cancellation")
    print("PASS: public reads, organizer authority, attendee leave, past rejection, idempotence, and synchronized locked capacity verified")


def assert_storage_ownership(base: str, owner_token: str, other_token: str) -> None:
    marker = f"rls-harness-{uuid.uuid4().hex}"
    owner_key = f"{OWNER_ID}/{marker}/owner.jpg"
    cross_key = f"{OWNER_ID}/{marker}/cross.jpg"
    legacy_key = f"{marker}/legacy.jpg"
    upload = b"boarded-social-storage-harness"
    owner_upload = expect_api_result(request_storage("POST", base, owner_key, owner_token, upload), "owner social-media upload")
    if owner_upload.status not in {200, 201}:
        fail(f"owner social-media upload failed: HTTP {owner_upload.status} {owner_upload.body!r}")
    try:
        public_read = expect_api_result(request_storage("GET", base, owner_key), "public social-media read")
        if public_read.status != 200:
            fail(f"public social-media read failed: HTTP {public_read.status} {public_read.body!r}")
        assert_rejected(expect_api_result(request_storage("POST", base, cross_key, other_token, upload), "cross-prefix upload"), "cross-prefix upload")
        assert_rejected(expect_api_result(request_storage("POST", base, legacy_key, owner_token, upload), "legacy-prefix upload"), "legacy-prefix upload")
        assert_rejected(expect_api_result(request_storage("POST", base, cross_key, payload=upload), "anonymous upload"), "anonymous upload")
    finally:
        deleted = expect_api_result(request_storage("DELETE", base, owner_key, owner_token), "owner social-media cleanup")
        if deleted.status not in {200, 204}:
            fail(f"owner social-media cleanup failed: HTTP {deleted.status} {deleted.body!r}")
    print("PASS: social-media public read and first-path authenticated ownership verified")

def assert_community_prerequisites(base: str, owner_token: str, other_token: str) -> None:
    # 1. Venues RLS & immutability
    public_venue = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/venues?id=eq.{PUBLIC_VENUE_ID}"), "anon public venue read"), "anon public venue read")
    if len(public_venue) != 1 or public_venue[0].get("name") != "Stone Crag":
        fail(f"anonymous read could not see public venue: {public_venue!r}")

    private_venue_anon = expect_api_result(request_json("GET", f"{base}/rest/v1/venues?id=eq.{PRIVATE_VENUE_ID}"), "anon private venue read")
    if private_venue_anon.status not in {200, 401, 403} or (private_venue_anon.status == 200 and private_venue_anon.body):
        fail(f"anonymous read leaked private venue: {private_venue_anon.body!r}")

    private_venue_other = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/venues?id=eq.{PRIVATE_VENUE_ID}", other_token), "owner private venue read"), "owner private venue read")
    if len(private_venue_other) != 1 or private_venue_other[0].get("name") != "Secret Cave":
        fail(f"owner could not see own private venue: {private_venue_other!r}")

    private_venue_cross = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/venues?id=eq.{PRIVATE_VENUE_ID}", owner_token), "cross-user private venue read"), "cross-user private venue read")
    if private_venue_cross:
        fail(f"cross-user read leaked private venue: {private_venue_cross!r}")

    # Cross-user venue update/delete denied
    assert_no_rows(expect_api_result(request_json("PATCH", f"{base}/rest/v1/venues?id=eq.{PRIVATE_VENUE_ID}", owner_token, {"name": "hacked"}), "cross venue update"), "cross venue update")
    assert_no_rows(expect_api_result(request_json("DELETE", f"{base}/rest/v1/venues?id=eq.{PRIVATE_VENUE_ID}", owner_token), "cross venue delete"), "cross venue delete")

    # Venue user_id immutability
    assert_rejected(expect_api_result(request_json("PATCH", f"{base}/rest/v1/venues?id=eq.{PUBLIC_VENUE_ID}", owner_token, {"user_id": OTHER_ID}), "venue user_id mutation"), "venue user_id mutation")

    # 2. Extended Routes RLS & nullable wall_id
    outdoor_route = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{OUTDOOR_ROUTE_ID}"), "anon outdoor route read"), "anon outdoor route read")
    if len(outdoor_route) != 1 or outdoor_route[0].get("wall_id") is not None or outdoor_route[0].get("discipline") != "sport":
        fail(f"outdoor route did not return correct nullable wall_id or discipline: {outdoor_route!r}")

    private_route_anon = expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PRIVATE_ROUTE_ID}"), "anon private route read")
    if private_route_anon.status not in {200, 401, 403} or (private_route_anon.status == 200 and private_route_anon.body):
        fail(f"anonymous read leaked private route: {private_route_anon.body!r}")

    private_route_cross = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PRIVATE_ROUTE_ID}", owner_token), "cross private route read"), "cross private route read")
    if private_route_cross:
        fail(f"cross-user read leaked private route: {private_route_cross!r}")

    # 3. Follows table authorization & lifecycle
    follows_read = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/follows?follower_id=eq.{OWNER_ID}"), "anon follows read"), "anon follows read")
    if len(follows_read) != 1 or follows_read[0].get("following_id") != OTHER_ID:
        fail(f"public follows read failed: {follows_read!r}")

    # No self-follow constraint
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/follows", owner_token, {"follower_id": OWNER_ID, "following_id": OWNER_ID}), "self follow rejected"), "self follow rejected")

    # Cross-user follow insertion denied
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/follows", other_token, {"follower_id": OWNER_ID, "following_id": FILLER_ID}), "cross follow insert"), "cross follow insert")

    # Cross-user follow deletion denied
    assert_no_rows(expect_api_result(request_json("DELETE", f"{base}/rest/v1/follows?follower_id=eq.{OWNER_ID}&following_id=eq.{OTHER_ID}", other_token), "cross follow delete"), "cross follow delete")

    # Follow keys immutable
    follow_patch = expect_api_result(request_json("PATCH", f"{base}/rest/v1/follows?follower_id=eq.{OWNER_ID}&following_id=eq.{OTHER_ID}", owner_token, {"following_id": FILLER_ID}), "follow key mutation")
    assert_mutation_denied(follow_patch, "follow key mutation")
    follows_after = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/follows?follower_id=eq.{OWNER_ID}"), "follows check after patch"), "follows check after patch")
    if len(follows_after) != 1 or follows_after[0].get("following_id") != OTHER_ID:
        fail(f"follow key was altered by mutation: {follows_after!r}")

    # 4. Route Bookmarks (owner-only saved routes)
    anon_bookmarks = expect_api_result(request_json("GET", f"{base}/rest/v1/route_bookmarks"), "anon bookmarks read")
    if anon_bookmarks.status not in {200, 401, 403} or (anon_bookmarks.status == 200 and anon_bookmarks.body):
        fail(f"anonymous read leaked bookmarks: {anon_bookmarks.body!r}")

    owner_bookmarks = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/route_bookmarks", owner_token), "owner bookmarks read"), "owner bookmarks read")
    if len(owner_bookmarks) != 1 or owner_bookmarks[0].get("route_id") != OUTDOOR_ROUTE_ID:
        fail(f"owner could not read own bookmark: {owner_bookmarks!r}")

    other_bookmarks = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/route_bookmarks", other_token), "other bookmarks read"), "other bookmarks read")
    if other_bookmarks:
        fail(f"other user read owner bookmarks: {other_bookmarks!r}")

    # Saving inaccessible private route rejected by WITH CHECK
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/route_bookmarks", owner_token, {"user_id": OWNER_ID, "route_id": PRIVATE_ROUTE_ID}), "saving private route rejected"), "saving private route rejected")

    # Cross-user bookmark insertion rejected
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/route_bookmarks", owner_token, {"user_id": OTHER_ID, "route_id": OUTDOOR_ROUTE_ID}), "cross bookmark insert"), "cross bookmark insert")

    # Bookmark keys immutable
    bookmark_patch = expect_api_result(request_json("PATCH", f"{base}/rest/v1/route_bookmarks?user_id=eq.{OWNER_ID}&route_id=eq.{OUTDOOR_ROUTE_ID}", owner_token, {"route_id": OWNER_ROUTE_ID}), "bookmark key mutation")
    assert_mutation_denied(bookmark_patch, "bookmark key mutation")
    bookmarks_after = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/route_bookmarks", owner_token), "bookmarks check after patch"), "bookmarks check after patch")
    if len(bookmarks_after) != 1 or bookmarks_after[0].get("route_id") != OUTDOOR_ROUTE_ID:
        fail(f"bookmark key was altered by mutation: {bookmarks_after!r}")

    # 5. Activity Events (inbox privacy, tampering denial, and trigger execution)
    anon_activity = expect_api_result(request_json("GET", f"{base}/rest/v1/activity_events"), "anon activity read")
    if anon_activity.status not in {200, 401, 403} or (anon_activity.status == 200 and anon_activity.body):
        fail(f"anonymous read leaked activity events: {anon_activity.body!r}")

    # Direct client insert denied
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/activity_events", owner_token, {"recipient_id": OTHER_ID, "actor_id": OWNER_ID, "kind": "follow"}), "client activity forging denied"), "client activity forging denied")

    # Follow trigger generated event for OTHER_ID
    other_activity = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/activity_events", other_token), "other activity inbox read"), "other activity inbox read")
    follow_event = next((e for e in other_activity if e.get("kind") == "follow" and e.get("actor_id") == OWNER_ID), None)
    if not follow_event:
        fail(f"follow trigger did not create activity event for followed user: {other_activity!r}")

    # Recipient mark-read works
    mark_read = expect_api_result(request_json("PATCH", f"{base}/rest/v1/activity_events?id=eq.{follow_event['id']}", other_token, {"read_at": datetime.now(timezone.utc).isoformat()}), "mark activity read")
    if mark_read.status not in {200, 204}:
        fail(f"recipient could not mark activity read: HTTP {mark_read.status} {mark_read.body!r}")

    # Activity event tampering denied
    assert_rejected(expect_api_result(request_json("PATCH", f"{base}/rest/v1/activity_events?id=eq.{follow_event['id']}", other_token, {"kind": "like"}), "activity kind tampering"), "activity kind tampering")
    assert_rejected(expect_api_result(request_json("PATCH", f"{base}/rest/v1/activity_events?id=eq.{follow_event['id']}", other_token, {"actor_id": FILLER_ID}), "activity actor tampering"), "activity actor tampering")

    # Cross-user read/update/delete denied
    owner_activity = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/activity_events", owner_token), "owner activity read"), "owner activity read")
    if any(e.get("id") == follow_event["id"] for e in owner_activity):
        fail(f"owner read other user's activity event: {owner_activity!r}")

    # 6. Community RPCs
    # get_explore_routes
    explore_routes = rows(rpc(base, "get_explore_routes", owner_token, {"page_size": 20}), "get_explore_routes")
    explore_ids = [r.get("id") for r in explore_routes]
    if OWNER_ROUTE_ID not in explore_ids or OUTDOOR_ROUTE_ID not in explore_ids:
        fail(f"explore routes missed public routes: {explore_ids!r}")
    if PRIVATE_ROUTE_ID in explore_ids:
        fail(f"explore routes leaked private route: {explore_ids!r}")

    # Saved-only filter
    saved_explore = rows(rpc(base, "get_explore_routes", owner_token, {"saved_only": True, "page_size": 20}), "saved explore routes")
    if len(saved_explore) != 1 or saved_explore[0].get("id") != OUTDOOR_ROUTE_ID:
        fail(f"saved-only filter did not return exactly the bookmarked route: {saved_explore!r}")

    # search_climbers
    climbers = rows(rpc(base, "search_climbers", owner_token, {"search_text": "rls-harness"}), "search_climbers")
    other_climber = next((c for c in climbers if c.get("id") == OTHER_ID), None)
    if not other_climber or other_climber.get("is_followed") is not True or other_climber.get("follower_count") != 1:
        fail(f"search_climbers did not return correct is_followed or follower_count: {other_climber!r}")

    # get_activity RPC
    activity_rpc = rows(rpc(base, "get_activity", other_token, {"page_size": 20}), "get_activity rpc")
    if not any(e.get("id") == follow_event["id"] and isinstance(e.get("actor"), dict) for e in activity_rpc):
        fail(f"get_activity RPC did not return caller inbox event with nested actor: {activity_rpc!r}")

    print("PASS: community prerequisites: venues, outdoor routes, follows, bookmarks, activity inbox, and discovery RPCs verified")

    # 7. Public routes on private parents (underlying wall / venue visibility protection)
    # Direct route access: non-owners and anon cannot read public routes with private parents
    anon_pw_route = expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PUBLIC_ROUTE_PRIVATE_WALL_ID}"), "anon pub-route priv-wall read")
    if anon_pw_route.status not in {200, 401, 403} or (anon_pw_route.status == 200 and anon_pw_route.body):
        fail(f"anon read leaked public route on private wall: {anon_pw_route.body!r}")

    owner_pw_route = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PUBLIC_ROUTE_PRIVATE_WALL_ID}", owner_token), "cross pub-route priv-wall read"), "cross pub-route priv-wall read")
    if owner_pw_route:
        fail(f"non-owner read leaked public route on private wall: {owner_pw_route!r}")

    other_pw_route = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PUBLIC_ROUTE_PRIVATE_WALL_ID}", other_token), "owner pub-route priv-wall read"), "owner pub-route priv-wall read")
    if len(other_pw_route) != 1 or other_pw_route[0].get("id") != PUBLIC_ROUTE_PRIVATE_WALL_ID:
        fail(f"wall owner could not read own public route on own private wall: {other_pw_route!r}")

    anon_pv_route = expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PUBLIC_ROUTE_PRIVATE_VENUE_ID}"), "anon pub-route priv-venue read")
    if anon_pv_route.status not in {200, 401, 403} or (anon_pv_route.status == 200 and anon_pv_route.body):
        fail(f"anon read leaked public route on private venue: {anon_pv_route.body!r}")

    owner_pv_route = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{PUBLIC_ROUTE_PRIVATE_VENUE_ID}", owner_token), "cross pub-route priv-venue read"), "cross pub-route priv-venue read")
    if owner_pv_route:
        fail(f"non-owner read leaked public route on private venue: {owner_pv_route!r}")

    # Bookmarking public routes with private parents is rejected for non-owners
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/route_bookmarks", owner_token, {"user_id": OWNER_ID, "route_id": PUBLIC_ROUTE_PRIVATE_WALL_ID}), "bookmark pub-route priv-wall"), "bookmark pub-route priv-wall")
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/route_bookmarks", owner_token, {"user_id": OWNER_ID, "route_id": PUBLIC_ROUTE_PRIVATE_VENUE_ID}), "bookmark pub-route priv-venue"), "bookmark pub-route priv-venue")

    # Explore RPC excludes public routes on private parents for non-owners, and never leaks wall image
    anon_explore = rows(rpc(base, "get_explore_routes", payload={"page_size": 50}), "anon explore private parents")
    anon_explore_ids = [r.get("id") for r in anon_explore]
    if PUBLIC_ROUTE_PRIVATE_WALL_ID in anon_explore_ids or PUBLIC_ROUTE_PRIVATE_VENUE_ID in anon_explore_ids:
        fail(f"explore leaked public route on private parent: {anon_explore_ids!r}")
    serialized_explore = json.dumps(anon_explore)
    if SECRET_WALL_IMAGE_URL in serialized_explore:
        fail(f"explore leaked private wall image URL: {serialized_explore}")

    other_explore = rows(rpc(base, "get_explore_routes", other_token, {"page_size": 50}), "owner explore private parents")
    other_explore_ids = [r.get("id") for r in other_explore]
    if PUBLIC_ROUTE_PRIVATE_WALL_ID not in other_explore_ids or PUBLIC_ROUTE_PRIVATE_VENUE_ID not in other_explore_ids:
        fail(f"parent owner explore missed own routes: {other_explore_ids!r}")

    # Feed RPC on post featuring attempt on public route with private wall:
    # Non-owner viewer receives route = None, featured_attempt.route_id = None, and no private wall image URL
    owner_feed_check = rows(rpc(base, "get_session_feed", owner_token, {"post_filter": OTHER_POST_PRIVATE_PARENT_ID, "page_size": 1}), "owner check feed private parent")
    if len(owner_feed_check) != 1:
        fail(f"feed did not return post with private parent: {owner_feed_check!r}")
    priv_parent_post = owner_feed_check[0]
    if priv_parent_post.get("route") is not None:
        fail(f"feed leaked route for public route on private wall: {priv_parent_post.get('route')!r}")
    if priv_parent_post.get("session", {}).get("featured_attempt", {}).get("route_id") is not None:
        fail(f"feed leaked route_id for public route on private wall: {priv_parent_post!r}")
    if SECRET_WALL_IMAGE_URL in json.dumps(priv_parent_post):
        fail(f"feed leaked private wall image URL: {priv_parent_post!r}")

    # Owner viewer receives route populated with wall image URL
    other_feed_check = rows(rpc(base, "get_session_feed", other_token, {"post_filter": OTHER_POST_PRIVATE_PARENT_ID, "page_size": 1}), "parent owner feed check")
    if len(other_feed_check) != 1:
        fail(f"parent owner feed did not return post: {other_feed_check!r}")
    owner_view_post = other_feed_check[0]
    if owner_view_post.get("route") is None or owner_view_post.get("route", {}).get("id") != PUBLIC_ROUTE_PRIVATE_WALL_ID:
        fail(f"parent owner could not see own route on private wall in feed: {owner_view_post!r}")
    if owner_view_post.get("route", {}).get("image_url") != SECRET_WALL_IMAGE_URL:
        fail(f"parent owner expected wall image URL {SECRET_WALL_IMAGE_URL!r}, got {owner_view_post.get('route', {}).get('image_url')!r}")

    # 8. increment_route_view respects parent visibility (DATA-V1-004)
    owner_view = expect_api_result(rpc(base, "increment_route_view", owner_token, {"target_route_id": OWNER_ROUTE_ID}), "increment route view accessible")
    if owner_view.status != 200 or not isinstance(owner_view.body, int):
        fail(f"increment_route_view on accessible route failed: {owner_view!r}")
    priv_parent_view = expect_api_result(rpc(base, "increment_route_view", owner_token, {"target_route_id": PUBLIC_ROUTE_PRIVATE_WALL_ID}), "increment route view priv parent")
    if priv_parent_view.status != 200 or priv_parent_view.body is not None:
        fail(f"increment_route_view on route with private parent expected null, got {priv_parent_view.body!r}")

    # 9. 1:1 comment provenance and selective deletion (DATA-V1-005)
    c1_id = str(uuid.uuid4())
    c2_id = str(uuid.uuid4())
    c1_res = expect_api_result(request_json("POST", f"{base}/rest/v1/session_post_comments", owner_token, {"id": c1_id, "post_id": OTHER_POST_ID, "user_id": OWNER_ID, "content": "Comment 1"}), "comment 1 insert")
    # Comment id is immutable to prevent stranding activity event provenance
    assert_rejected(expect_api_result(request_json("PATCH", f"{base}/rest/v1/session_post_comments?id=eq.{c1_id}", owner_token, {"id": str(uuid.uuid4())}), "comment id mutation"), "comment id mutation")
    c2 = expect_api_result(request_json("POST", f"{base}/rest/v1/session_post_comments", owner_token, {"id": c2_id, "post_id": OTHER_POST_ID, "user_id": OWNER_ID, "content": "Comment 2"}), "comment 2 insert")
    other_comm_events = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/activity_events?recipient_id=eq.{OTHER_ID}&kind=eq.comment", other_token), "other comment activity read"), "other comment activity read")
    if len(other_comm_events) < 2:
        fail(f"two comments did not create two distinct activity events: {other_comm_events!r}")
    expect_api_result(request_json("DELETE", f"{base}/rest/v1/session_post_comments?id=eq.{c1_id}", owner_token), "delete comment 1")
    other_after_del = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/activity_events?recipient_id=eq.{OTHER_ID}&kind=eq.comment", other_token), "activity after delete c1"), "activity after delete c1")
    if len(other_after_del) != len(other_comm_events) - 1:
        fail(f"deleting comment 1 did not remove exactly one activity event: before={len(other_comm_events)} after={len(other_after_del)}")
    expect_api_result(request_json("DELETE", f"{base}/rest/v1/session_post_comments?id=eq.{c2_id}", owner_token), "delete comment 2")

    # 10. Parent deletion marks surviving routes private and records tombstones (DATA-V1-002)
    disp_wall_id = str(uuid.uuid4())
    disp_route_id = str(uuid.uuid4())
    run_psql(
        f"INSERT INTO public.walls (id, user_id, name, description, image_url, is_public) VALUES ({sql_quote(disp_wall_id)}, {sql_quote(OTHER_ID)}, 'Disp Wall', 'Priv', 'https://secret.example.com/disp.jpg', false);"
        f"INSERT INTO public.routes (id, user_id, wall_id, name, is_public) VALUES ({sql_quote(disp_route_id)}, {sql_quote(OTHER_ID)}, {sql_quote(disp_wall_id)}, 'Disp Route', true);"
    )
    expect_api_result(request_json("DELETE", f"{base}/rest/v1/walls?id=eq.{disp_wall_id}", other_token), "delete private wall")
    disp_route_check = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{disp_route_id}", other_token), "check disp route after wall delete"), "check disp route after wall delete")
    if len(disp_route_check) != 1 or disp_route_check[0].get("is_public") is not False:
        fail(f"child route was not privatized after private wall deletion: {disp_route_check!r}")
    disp_anon = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{disp_route_id}"), "anon read disp route"), "anon read disp route")
    if disp_anon:
        fail(f"anonymous read saw child route after private wall deletion: {disp_anon!r}")
    run_psql(f"DELETE FROM public.routes WHERE id = {sql_quote(disp_route_id)}; DELETE FROM public.deleted_private_walls WHERE wall_id = {sql_quote(disp_wall_id)};")

    # 11. deleted_private_walls table has RLS enabled and all privileges revoked (DATA-V1R-002)
    anon_tomb = expect_api_result(request_json("GET", f"{base}/rest/v1/deleted_private_walls"), "anon deleted_private_walls read")
    if anon_tomb.status not in {401, 403, 404} and not (anon_tomb.status == 200 and not anon_tomb.body):
        fail(f"anon accessed deleted_private_walls: HTTP {anon_tomb.status} {anon_tomb.body!r}")
    auth_tomb = expect_api_result(request_json("GET", f"{base}/rest/v1/deleted_private_walls", owner_token), "auth deleted_private_walls read")
    if auth_tomb.status not in {401, 403, 404} and not (auth_tomb.status == 200 and not auth_tomb.body):
        fail(f"auth accessed deleted_private_walls: HTTP {auth_tomb.status} {auth_tomb.body!r}")
    assert_rejected(expect_api_result(request_json("POST", f"{base}/rest/v1/deleted_private_walls", owner_token, {"wall_id": "forged"}), "insert deleted_private_walls"), "insert deleted_private_walls")

    # 12. NULL-visibility wall deletion privatizes child routes (DATA-V1-002)
    disp_null_wall_id = str(uuid.uuid4())
    disp_null_route_id = str(uuid.uuid4())
    run_psql(
        f"INSERT INTO public.walls (id, user_id, name, description, image_url, is_public) VALUES ({sql_quote(disp_null_wall_id)}, {sql_quote(OTHER_ID)}, 'Disp Null Wall', 'Null priv', 'https://secret.example.com/disp-null.jpg', NULL);"
        f"INSERT INTO public.routes (id, user_id, wall_id, name, is_public) VALUES ({sql_quote(disp_null_route_id)}, {sql_quote(OTHER_ID)}, {sql_quote(disp_null_wall_id)}, 'Disp Null Route', true);"
    )
    expect_api_result(request_json("DELETE", f"{base}/rest/v1/walls?id=eq.{disp_null_wall_id}", other_token), "delete null-visibility wall")
    disp_null_check = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{disp_null_route_id}", other_token), "check disp null route after wall delete"), "check disp null route after wall delete")
    if len(disp_null_check) != 1 or disp_null_check[0].get("is_public") is not False:
        fail(f"child route was not privatized after null-visibility wall deletion: {disp_null_check!r}")
    disp_null_anon = rows(expect_api_result(request_json("GET", f"{base}/rest/v1/routes?id=eq.{disp_null_route_id}"), "anon read disp null route"), "anon read disp null route")
    if disp_null_anon:
        fail(f"anonymous read saw child route after null-visibility wall deletion: {disp_null_anon!r}")
    run_psql(f"DELETE FROM public.routes WHERE id = {sql_quote(disp_null_route_id)}; DELETE FROM public.deleted_private_walls WHERE wall_id = {sql_quote(disp_null_wall_id)};")

    # 13. increment_route_view recovers NULL counter to 1 (DATA-V1R-005)
    null_view_route_id = str(uuid.uuid4())
    run_psql(
        f"INSERT INTO public.routes (id, user_id, wall_id, name, is_public, view_count) VALUES ({sql_quote(null_view_route_id)}, {sql_quote(OWNER_ID)}, 'rls-harness-wall', 'Null Counter Route', true, NULL);"
    )
    first_inc = expect_api_result(rpc(base, "increment_route_view", owner_token, {"target_route_id": null_view_route_id}), "first increment null counter")
    if first_inc.status != 200 or first_inc.body != 1:
        fail(f"increment_route_view on NULL counter expected 1, got {first_inc!r}")
    second_inc = expect_api_result(rpc(base, "increment_route_view", owner_token, {"target_route_id": null_view_route_id}), "second increment null counter")
    if second_inc.status != 200 or second_inc.body != 2:
        fail(f"increment_route_view on second call expected 2, got {second_inc!r}")
    run_psql(f"DELETE FROM public.routes WHERE id = {sql_quote(null_view_route_id)};")



def run() -> None:
    base = os.environ.get(LOCAL_URL_ENV, DEFAULT_LOCAL_URL).rstrip("/")
    ensure_backend(base)
    run_psql("SELECT 1;")
    try:
        setup_fixtures()
        owner_token = login(base, User(OWNER_ID, OWNER_EMAIL))

        other_token = login(base, User(OTHER_ID, OTHER_EMAIL))
        assert_route_ownership(base, owner_token, other_token)
        assert_public_profiles_and_feed(base, owner_token, other_token)
        assert_private_sessions_and_attempts(base, owner_token, other_token)
        assert_community_prerequisites(base, owner_token, other_token)
        assert_social_mutations(base, owner_token, other_token)
        assert_concurrent_publish_reopen(base, owner_token)
        assert_public_meetups_and_joins(base, owner_token, other_token)
        assert_storage_ownership(base, owner_token, other_token)
    finally:
        cleanup_fixtures()
        print("PASS: fixed UUID auth and social fixtures cleaned up")


def main() -> int:
    try:
        run()
    except HarnessError as exc:
        print(f"FAIL: {exc}", file=sys.stderr)
        return 1
    except Exception as exc:
        print(f"FAIL: unexpected harness error: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
